function buildRenderAudioSources(scenes, clips, fps) {
  const sources = [];
  let startFrame = 0;
  for (const scene of scenes) {
    if (scene.audioUrl) {
      sources.push({
        url: scene.audioUrl,
        delayMs: startFrame / fps * 1e3,
        volume: scene.audioVolume ?? 1
      });
    }
    startFrame += scene.durationInFrames;
  }
  for (const clip of clips) {
    sources.push({
      url: clip.url,
      delayMs: clip.startFrame / fps * 1e3,
      volume: clip.volume,
      startFromSec: clip.startFrom,
      durationSec: clip.durationInFrames / fps
    });
  }
  return sources;
}
